// Activity data for both camps: the four deck arrays and the category map.

const CATMAP = {"bioenergy": {"l": "Biology + Energy", "c": "#63d9a0"}, "field": {"l": "Field Science", "c": "#4dd4ac"}, "biomimicry": {"l": "Biomimicry", "c": "#7bd88f"}, "ecology": {"l": "Ecology", "c": "#5cc98a"}, "materials": {"l": "Materials", "c": "#9bdc6a"}, "data": {"l": "Data + Climate", "c": "#56cfe1"}, "biomed": {"l": "Biomedical", "c": "#ef6f6f"}, "mechanics": {"l": "Mechanics", "c": "#f4a261"}, "waves": {"l": "Waves + Sound", "c": "#6ea8fe"}, "optics": {"l": "Optics + Light", "c": "#f0d060"}, "cs": {"l": "Computing", "c": "#56cfe1"}, "design": {"l": "Design", "c": "#ce7cf4"}};
const TREES_DECK = [{"code": "TTT-00", "welcome": true, "t": "Welcome to From Trees to Tech", "sub": "Field. Forest. Future. Meet the week and your team.", "cat": "field", "icon": "🌲", "buildMin": 0, "mission": "Get oriented, meet your team, and learn how the week works: build it, measure it, defend it with data.", "camp": "trees", "science": [{"t": "The week ahead", "demo": null, "b": "From Trees to Tech is a week of missions where you copy nature's best engineering. Every station runs the same loop: predict what will happen, build or solve it, test it, get scored, then redesign and defend your result with data."}, {"t": "How you win", "demo": null, "b": "Each station is scored out of 100 for design, data, teamwork, and explaining, so a fast finish does not win on its own. Your week is your best 9 of 12 stations, and improving after a redesign earns a comeback bonus."}, {"t": "Tickets, awards, and prizes", "demo": null, "b": "Your team earns tickets for safety, teamwork, sharp questions, and creative designs, and spends them at the store just for fun, so they never change your score. There are daily awards too, plus end prizes for the top teams and the most improved."}, {"t": "Safety first", "demo": null, "b": "We match safety gear to the task: gloves at the wet and mud stations, and sun protection and water for the outdoor blocks. Listen for your team's safety captain, keep your space clean, and tell a counselor about any spill or injury."}, {"t": "Fight the bite outside", "demo": null, "b": "Our outdoor stations are where ticks and mosquitoes live, so bring your own bug spray, wear long pants tucked into your socks, and stay in the middle of the trail. Afterward, do a tick check with a buddy, shower at home, and tell a counselor if you find one."}, {"t": "Leaves of three, let it be", "demo": null, "b": "Poison ivy grows along the trails and the pond, and its oil causes an itchy rash. Leaves of three, let it be: stay on the path and do not touch the plants. If you brush one, tell a counselor and wash with soap and water."}], "materials": [{"n": "Activity handout", "q": "1 per camper"}, {"n": "Pencil", "q": "1 per camper"}, {"n": "Name tag (card or masking tape)", "q": "1 per camper"}, {"n": "Gloves and safety gear", "q": "staged at each station"}], "steps": [{"t": "Welcome and names", "b": "Say hello, learn the room and the week, and put on your name tag (a card or masking tape)."}, {"t": "Form your team", "b": "Join one of the four teams and pick a quick team name with your counselor."}, {"t": "Safety walk", "b": "Counselors point out the exits, the wet-station rules, and where the safety gear lives."}, {"t": "First mission", "b": "Head into the first station and start the design loop."}], "compete": ["Design and build: 30", "Clean data: 25", "Teamwork: 20", "Explanation and defense: 25"], "scoring": "This is how every station is scored. Your week total is your best 9 of 12. The welcome itself is not scored.", "debrief": ["What is one thing nature does better than our machines?", "What will your team be great at this week?", "This week, what will count as strong evidence for your design?"], "source": "From Trees to Tech orientation"}, {"code": "TTT-01", "t": "MudWatt Bioelectric League", "sub": "Turn a cup of mud into a living battery", "cat": "bioenergy", "icon": "🔋", "buildMin": 80, "mission": "Can your team make mud generate electricity and defend your design with data?", "science": [{"t": "Electrogenic bacteria", "demo": "mudwatt", "b": "Some bacteria already in ordinary soil are electrogenic: as they digest nutrients, they push spare electrons onto surfaces outside their cells. Bury a carbon-felt anode in oxygen-free mud and these microbes coat it, feeding it a steady stream of electrons."}, {"t": "Completing the circuit", "demo": null, "b": "Electrons leave the anode, run through the wire, the 100 kΩ resistor, and the multimeter, reaching the cathode in the air on top, where they join oxygen and protons to form water. More microbes mean a higher voltage on the multimeter. Power is roughly voltage times current."}], "materials": [{"n": "Carbon felt electrodes (cut as a flag with a dry tab)", "q": "2 per cell"}, {"n": "24 oz deli cups", "q": "1 per cell"}, {"n": "100 kΩ resistor", "q": "1 per cell"}, {"n": "Alligator leads", "q": "3 to 4 per cell"}, {"n": "Fresh soil or mud", "q": "fill each vessel"}, {"n": "Nitrile gloves", "q": "per student"}, {"n": "Trash-bag drip liner", "q": "1 per cell"}, {"n": "Fuel", "q": "sugar cube (measured)"}, {"n": "Labels and tape", "q": "shared"}, {"n": "Multimeters", "q": "required, 1 per team"}], "steps": [{"t": "Inoculate the mud", "b": "Gloves on. Pack the vessel with sponge-damp soil. The bacteria you need are already in the dirt, so no culture is required."}, {"t": "Place the electrodes", "b": "Bury the anode near the bottom and smooth mud over it so no air reaches it. Rest the cathode flat on top, exposed to the air."}, {"t": "Add a measured fuel", "b": "Mix in a small, measured amount of one approved fuel. Record exactly how much. This is the food that drives the voltage."}, {"t": "Connect and read a baseline", "b": "Clip the dry felt tabs to a 100 kΩ resistor, set the multimeter to DC millivolts, and read the voltage across the resistor. Day one is often weak; the biofilm needs time."}, {"t": "Control one variable", "b": "Pick ONE thing to test all week: fuel type, fuel amount, moisture, or anode packing. Change only that, predict the effect, and compare to baseline."}], "compete": ["Peak voltage reading: 35", "Daily data log quality: 20", "Controlled-variable design: 15", "Redesign or maintenance plan: 15", "Final explanation: 15"], "scoring": "Highest combined score across the week wins the league. Evidence beats luck.", "debrief": ["Which design change moved your readings the most, and how do you know?", "Why must the anode stay buried and the cathode stay in air?", "How is your weekly log like the work of an energy engineer?"], "source": "Ohio State Microbial Fuel Cell Learning Center", "camp": "trees"}, {"code": "TTT-02", "t": "Forest Sensor Sprint", "sub": "Site the smartest place for a campus tree sensor", "cat": "field", "icon": "🌳", "buildMin": 80, "mission": "Find the smartest place to install a future campus tree sensor.", "science": [{"t": "Microclimate varies in meters", "demo": null, "b": "Temperature, humidity, light, and soil moisture can change sharply over short distances. A spot under a dense canopy can be several degrees cooler and far more humid than open lawn a few steps away. Good sensor placement starts with measuring, not guessing."}, {"t": "Evidence-based siting", "demo": null, "b": "A useful sensor sits where its readings represent the area you care about and where it will not be disturbed. Teams collect data at field stations, then argue for one location using their own numbers plus an efficient route between checkpoints."}], "materials": [{"n": "Clipboards", "q": "4 (one per team)"}, {"n": "Paper clinometers", "q": "4 (one per team)"}, {"n": "Temperature and humidity meters", "q": "4 (one per team)"}, {"n": "Soil meters", "q": "4 (one per team); the soil meter also reads light"}, {"n": "Route cards", "q": "4 (one per team)"}, {"n": "Pencils", "q": "shared"}], "steps": [{"t": "Calibrate together", "b": "Take one reading as a whole group at a reference spot so every team's tools agree before they split up."}, {"t": "Run the field stations", "b": "Rotate through stations measuring temperature, humidity, light, and soil moisture. Record units every time."}, {"t": "Estimate tree height", "b": "Sight the treetop through the clinometer straw, read the angle off the plumb string, and use the standoff distance the instructor pre-marked with the long tape: tree height = eye height + distance x tan(angle)."}, {"t": "Plan an efficient route", "b": "Order your checkpoints to minimize backtracking. Note the route on the card."}, {"t": "Recommend one site", "b": "Pick one sensor location and defend it with your measurements, not opinion."}], "compete": ["Data accuracy: 30", "Route efficiency: 20", "Site recommendation evidence: 30", "Teamwork and field conduct: 20"], "scoring": "Best evidence-based recommendation with accurate measurements wins.", "debrief": ["Which measurement most influenced your choice?", "Where did two nearby spots disagree, and why?", "What would change your recommendation in winter?"], "source": "GLOBE Observer Trees; NASA MyNASAData Urban Heat Island", "camp": "trees"}, {"code": "TTT-03", "t": "Seed Dispersal Derby", "sub": "Engineer a seed that escapes its parent tree", "cat": "biomimicry", "icon": "🍃", "buildMin": 80, "mission": "Build a seed that escapes the parent tree without engines or throwing.", "science": [{"t": "Drag, lift, and hang time", "demo": "samara", "b": "A maple samara spins as it falls. The spinning wing pushes against the air and makes lift, so the seed drifts down slowly and even a light breeze carries it away from the shade of its parent. More surface area for the same mass usually means a longer, slower fall."}, {"t": "One variable at a time", "demo": null, "b": "Wing length, wing angle, and added mass all change flight. Engineers learn what each does by changing only one and comparing. Copying a natural strategy on purpose is biomimicry."}], "materials": [{"n": "Paper and cardstock", "q": "shared"}, {"n": "Paper clips", "q": "for mass"}, {"n": "Masking tape", "q": "shared"}, {"n": "String", "q": "shared"}, {"n": "Fan or marked lane", "q": "1 test zone"}, {"n": "Tape measure", "q": "1 shared, for distance"}, {"n": "Timers", "q": "per team"}], "steps": [{"t": "Study a real samara", "b": "Drop a maple seed or a model. Watch how the wing makes it spin and slow down."}, {"t": "Build a baseline seed", "b": "Make a simple winged seed with one paper clip for mass. Record a baseline drop time and distance."}, {"t": "Change one variable", "b": "Adjust wing length OR mass OR fold angle, only one. Predict the effect before testing."}, {"t": "Test for hang time and distance", "b": "Drop from the standard height or release in the fan lane. Time three trials and average."}, {"t": "Aim for a target", "b": "In a final round, try to land in a marked zone. Control plus distance both score."}], "compete": ["Distance traveled: 35", "Hang time: 25", "Target landing: 15", "Biomimicry explanation: 15", "Redesign improvement: 10"], "scoring": "Best combined distance, hang time, target landing, and explanation wins.", "debrief": ["Which change improved hang time without losing distance?", "Why does spinning slow the fall?", "Which tree's strategy did your final seed copy?"], "source": "Science Buddies Seed Dispersal; Project Learning Tree", "camp": "trees"}, {"code": "TTT-04", "t": "Xylem Pipeline Relay", "sub": "Move water uphill the way a tree does", "cat": "biomimicry", "icon": "💧", "buildMin": 80, "mission": "Move water uphill like a tree, faster and cleaner than rival teams.", "science": [{"t": "Capillary action", "demo": "capillary", "b": "Water climbs narrow spaces on its own. Water molecules stick to a surface (adhesion) and to each other (cohesion), so a thin column is pulled upward against gravity. Narrower channels and more wettable materials pull water higher and faster. Trees use this in their narrow xylem, but on its own it lifts water only about a meter. To reach the treetop, water evaporating from the leaves (transpiration) pulls the whole column up, like sipping through a straw."}, {"t": "Material and geometry", "demo": null, "b": "A folded paper towel, a cotton ball pulled into a strand, and a strip of cotton cloth each move water at a different rate. Capillary action only works in fine, connected channels that water can wet, so pre-wet your wick, keep it in firm contact, and use a gentle, short climb. Path length, slope, and contact all matter. Your team picks the material and route to deliver the most water to a target cup."}], "materials": [{"n": "Paper towels", "q": "shared"}, {"n": "Cotton balls", "q": "shared"}, {"n": "Cotton cloth strips", "q": "shared"}, {"n": "Cups", "q": "per team"}, {"n": "Food coloring", "q": "shared"}, {"n": "Trash bag table cover", "q": "per team"}, {"n": "Rulers", "q": "1 per team"}, {"n": "Elevation blocks", "q": "shared"}], "steps": [{"t": "Test three wick materials", "b": "Pre-wet each wick, then dip the paper towel, the cotton-ball strand, and the cotton cloth into colored water. Watch which climbs fastest and highest."}, {"t": "Pick a material and route", "b": "Choose your wick and lay out a path from the source cup up over a block to the target cup."}, {"t": "Run the first transfer", "b": "Start the wick and time how much water reaches the target in the time limit. Catch spills on the bag-covered table."}, {"t": "Reduce spill and length", "b": "Trim the path, improve contact, and re-run. Less spill and a shorter path usually deliver more."}, {"t": "Final delivery round", "b": "Run the best design for score. Water delivered, speed, and low spill all count."}], "compete": ["Water delivered: 40", "Speed: 20", "Least spill: 15", "Design explanation: 15", "Redesign gain: 10"], "scoring": "Most water delivered with speed, low spill, and a strong explanation wins.", "debrief": ["Which material moved water best, and why?", "How did slope change your delivery?", "Where does a real tree use this same effect?"], "source": "Science Buddies; plant water transport references", "camp": "trees"}, {"code": "TTT-05", "t": "Greenhouse Climate Controller", "sub": "Match plants to the right climate zone", "cat": "ecology", "icon": "🌿", "buildMin": 80, "mission": "Run the greenhouse controls for a plant that cannot complain, only wilt.", "science": [{"t": "Controlled environments", "demo": null, "b": "A greenhouse lets growers set temperature, humidity, and light to match what a plant needs. Get it wrong and the plant wilts, scorches, or molds. Every setting is a tradeoff: more light can mean more heat and faster drying."}, {"t": "Evidence from the tour", "demo": null, "b": "On the greenhouse tour you gather clues about real plant needs and real zone settings. Back at the table you match plant cards to climate dials using that evidence, then defend the layout."}], "materials": [{"n": "Plant profile cards", "q": "set"}, {"n": "Control dial boards", "q": "per team"}, {"n": "Clipboards", "q": "4 (one per team)"}, {"n": "Dry erase markers", "q": "per team"}, {"n": "Tour clue sheets", "q": "per team"}], "steps": [{"t": "Gather tour evidence", "b": "During the greenhouse visit, note real temperature, humidity, and light clues for different zones."}, {"t": "Read the plant cards", "b": "Each plant card lists needs and tolerances. Sort cards by what they require."}, {"t": "Set the climate dials", "b": "Match each plant to a zone and set temperature, humidity, and light on the dial board."}, {"t": "Resolve tradeoffs", "b": "When two plants want different things in one zone, choose the setting your evidence best supports."}, {"t": "Defend the layout", "b": "Explain each placement using a specific clue from the tour."}], "compete": ["Correct setting choices: 30", "Use of tour evidence: 25", "Explanation: 20", "Layout efficiency: 15", "Teamwork: 10"], "scoring": "Best plant-zone-control match supported by tour evidence wins.", "debrief": ["Which plant was hardest to place, and why?", "What tradeoff did you have to accept?", "How do real growers handle conflicting needs?"], "source": "Temple Ambler Greenhouse", "camp": "trees"}, {"code": "TTT-06", "t": "Pinecone Weather Machine", "sub": "A humidity sensor with no battery and no code", "cat": "biomimicry", "icon": "🌪", "buildMin": 80, "mission": "Build a humidity sensor with no battery and no code.", "science": [{"t": "Hygromorphs", "demo": null, "b": "A pine cone opens in dry air and closes when it is humid. Its scales are built from two layers of dead tissue that swell by different amounts when they absorb moisture, so the scale bends. No motor, no power, just material that responds to water in the air."}, {"t": "Bilayer biomimicry", "demo": null, "b": "You can copy this with a paper-and-tape bilayer. One layer absorbs moisture and grows; the other does not. The mismatch makes your indicator curl or straighten. The goal is a readable, repeatable humidity signal."}], "materials": [{"n": "Dry pine cones", "q": "shared"}, {"n": "Index cards", "q": "shared"}, {"n": "Wood skewers", "q": "shared"}, {"n": "Spray bottles", "q": "per team"}, {"n": "Rulers", "q": "per team"}, {"n": "Tape and fasteners", "q": "shared"}], "steps": [{"t": "Observe a real cone", "b": "Spray a pine cone and watch the scales close. Let it dry and watch them open."}, {"t": "Build a bilayer indicator", "b": "Tape a moisture-absorbing layer to a stiff backing so the strip bends when wet."}, {"t": "Add a readable scale", "b": "Mount the strip against a ruler or dial so the bend points to a number."}, {"t": "Run spray-and-dry trials", "b": "Spray, time the response, dry, repeat. Record how far and how fast it moves."}, {"t": "Redesign for speed", "b": "Adjust layer thickness or length to respond faster and more clearly."}], "compete": ["Response accuracy: 35", "Response speed: 20", "Readable output scale: 20", "Biomimicry explanation: 15", "Redesign quality: 10"], "scoring": "Most accurate, readable, and fast response after spray-and-dry trials wins.", "debrief": ["Why does a two-layer strip bend when only one layer swells?", "What made your indicator faster?", "Where would a no-power humidity sensor be useful?"], "source": "AskNature Pine Cones Strategy", "camp": "trees"}, {"code": "TTT-07", "t": "Pollinator Network Draft and Build", "sub": "Design a habitat that works all season", "cat": "ecology", "icon": "🐝", "buildMin": 80, "mission": "Draft a pollinator habitat that works all season, not just on the prettiest day.", "science": [{"t": "Networks, not single plants", "demo": null, "b": "Pollinators need food across the whole season, not just one bloom. A good habitat is a network: plants that flower in spring, summer, and fall, matched to the pollinators that visit them. Gaps in the calendar starve the system."}, {"t": "Native and clumping logic", "demo": null, "b": "Native plants tend to support local pollinators best, and planting in clumps helps insects find and work them efficiently. You draft plant and pollinator cards, then place them on a grid under these constraints."}], "materials": [{"n": "Plant cards", "q": "set"}, {"n": "Pollinator cards", "q": "set"}, {"n": "Grid boards", "q": "per team"}, {"n": "Stickers", "q": "shared"}, {"n": "Markers", "q": "shared"}, {"n": "Season tokens", "q": "per team"}], "steps": [{"t": "Draft your cards", "b": "Pick plant and pollinator cards. Note bloom season and which pollinators each plant supports."}, {"t": "Cover every season", "b": "Lay out plants so something blooms in spring, summer, and fall. Use season tokens to check coverage."}, {"t": "Apply native and clumping rules", "b": "Favor natives and group same plants in clumps so pollinators forage efficiently."}, {"t": "Connect the network", "b": "Make sure each pollinator has food across its active months, not just one."}, {"t": "Defend the design", "b": "Explain how your grid supports the most pollinators across the whole season."}], "compete": ["Seasonal coverage: 30", "Pollinator fit: 25", "Native and clumping logic: 20", "Layout clarity: 15", "Defense: 10"], "scoring": "Highest pollinator support across spring, summer, and fall wins.", "debrief": ["Where was the biggest gap in your bloom calendar?", "Why does clumping help pollinators?", "What happens to the network if one season is missing?"], "source": "USDA Pollinators; US Forest Service pollinator guidance", "camp": "trees"}, {"code": "TTT-08", "t": "Arboretum Eco-Quest", "sub": "Solve outdoor ecology checkpoints", "cat": "field", "icon": "🧭", "buildMin": 80, "mission": "Read the living collection and solve the checkpoints before time runs out.", "science": [{"t": "Observation as evidence", "demo": null, "b": "Identifying a tree is detective work: leaf shape, bark texture, branching pattern, and seeds are all clues. A dichotomous key turns those clues into a series of either-or choices that lead to a name."}, {"t": "Ecosystems in place", "demo": null, "b": "The arboretum is a living classroom of ecosystems. Each checkpoint asks you to observe carefully, classify what you see, and record the evidence that justifies your answer."}], "materials": [{"n": "Clue cards", "q": "set"}, {"n": "Route map", "q": "per team"}, {"n": "Clipboards", "q": "4 (one per team)"}, {"n": "Pencils", "q": "shared"}, {"n": "Evidence token bags", "q": "per team"}, {"n": "QR codes", "q": "optional"}], "steps": [{"t": "Get the map and rules", "b": "Each team gets a route map and the field-conduct rules. Stay on paths, stay together."}, {"t": "Solve each checkpoint", "b": "Use leaf, bark, and seed clues with the key to answer each station."}, {"t": "Collect evidence tokens", "b": "Record the specific clue that justifies each answer and collect the token."}, {"t": "Keep an efficient pace", "b": "Order your route to avoid backtracking; pace counts but accuracy counts more."}, {"t": "Check your answers", "b": "Before returning, confirm each answer cites real evidence, not a guess."}], "compete": ["Checkpoint accuracy: 50", "Evidence quality: 20", "Pace: 20", "Teamwork and conduct: 10"], "scoring": "Most accurate checkpoint solutions with safe field conduct wins.", "debrief": ["Which clue was most reliable for telling trees apart?", "Where did a key send you wrong, and why?", "What makes a good piece of field evidence?"], "source": "Temple Ambler Arboretum; Arboretum Explorer", "camp": "trees"}, {"code": "TTT-09", "t": "Minecraft Tree World Resilience Cup", "sub": "Design a climate-resilient landscape", "cat": "ecology", "icon": "🧱", "buildMin": 80, "mission": "Design a landscape that survives stress because of how it is built, not luck.", "science": [{"t": "Resilience by design", "demo": null, "b": "A resilient landscape keeps working after a shock: a storm, a drought, a heat wave. Diversity, connected habitats, shade, and water management all add resilience. Monocultures and bare ground fail fast."}, {"t": "Systems thinking", "demo": null, "b": "In Minecraft Education or a paper grid, you build a landscape and justify each choice with a nature-based strategy. The win is the most resilient, biodiverse, realistic design, not the prettiest screenshot."}], "materials": [{"n": "Minecraft Education devices or paper grid kit", "q": "per team"}, {"n": "Template", "q": "shared"}, {"n": "Rubric cards", "q": "per team"}, {"n": "Display timer", "q": "1"}], "steps": [{"t": "Pick a stress to survive", "b": "Choose the challenge your landscape must withstand: flood, drought, or heat."}, {"t": "Add resilience features", "b": "Build diversity, connected green space, shade, and water control into the design."}, {"t": "Support biodiversity", "b": "Include varied habitats so many species can live there, not just one."}, {"t": "Keep it realistic", "b": "Use strategies that would actually work outdoors, and label them."}, {"t": "Present and defend", "b": "Walk judges through how each feature adds resilience."}], "compete": ["Resilience features: 30", "Biodiversity support: 25", "Realism: 20", "Explanation: 15", "Build polish: 10"], "scoring": "Best climate-resilient design with accurate nature-based strategies wins.", "debrief": ["Which feature would help most in a real storm?", "Why does diversity add resilience?", "What in your build would fail first, and how would you fix it?"], "source": "Minecraft Education Biodiversity", "camp": "trees"}, {"code": "TTT-10", "t": "Tree Ring Climate Detective", "sub": "Read rings to reconstruct past climate", "cat": "data", "icon": "🪵", "buildMin": 80, "mission": "Read the rings to reconstruct the climate events a tree lived through.", "science": [{"t": "Rings as proxy data", "demo": "treering", "b": "A tree adds one ring per year. Wide rings mean a good growing season; narrow rings mean stress like drought, cold, or crowding. Because the tree cannot record numbers, the rings are a proxy: an indirect record of past climate."}, {"t": "Claim, evidence, reasoning", "demo": null, "b": "You infer events from ring patterns, then justify each call with the specific rings that support it. Scars, sudden narrowing, and runs of wide rings are your clues. Strong inferences cite the evidence."}], "materials": [{"n": "Printed ring cards", "q": "set"}, {"n": "Wood cookies or images", "q": "optional"}, {"n": "Answer boards", "q": "per team"}, {"n": "Timers", "q": "per team"}, {"n": "Claim-evidence cards", "q": "per team"}], "steps": [{"t": "Learn the ring code", "b": "Wide equals a favorable year, narrow a stress year (drought, cold, or crowding), scar a fire the tree survived. A ring is a proxy, not a thermometer."}, {"t": "Read the sequence", "b": "Work along the rings from center to bark, noting each pattern and the year it maps to."}, {"t": "Infer the events", "b": "Match patterns to likely events: drought, fire, a crowded stand, a recovery."}, {"t": "Cite your evidence", "b": "For each inference, point to the exact rings that justify it on a claim-evidence card."}, {"t": "Synthesize the story", "b": "Combine your inferences into one short climate history for the tree."}], "compete": ["Correct inferences: 40", "Evidence justification: 20", "Speed: 20", "Final synthesis: 20"], "scoring": "Most accurate climate-event inferences with claim-evidence-reasoning wins.", "debrief": ["Which pattern was easiest to misread?", "How is a tree ring like and unlike a thermometer?", "What other natural records store past climate?"], "source": "NOAA Tree Rings; NOAA Climate.gov; UCAR Center for Science Education", "camp": "trees"}, {"code": "TTT-11", "t": "Lotus Leaf Surface Sprint", "sub": "Engineer a self-cleaning, water-shedding surface", "cat": "materials", "icon": "💦", "buildMin": 80, "mission": "Build a surface that sheds water and dirt the way a lotus leaf does.", "science": [{"t": "Hydrophobic micro-texture", "demo": "lotus", "b": "A lotus leaf is covered in tiny bumps coated in wax. Water cannot settle into the texture, so droplets bead up into near-spheres and roll off, carrying dirt with them. The effect comes from roughness plus a water-repelling coating, not from being smooth."}, {"t": "Roughness plus coating", "demo": null, "b": "You texture and coat safe surfaces, then race droplets down a standard ramp. The best surface sheds water fast and leaves the least residue. Copying the leaf on purpose is biomimicry in materials engineering."}], "materials": [{"n": "Wax paper", "q": "shared"}, {"n": "Cardstock", "q": "shared"}, {"n": "Sandpaper strips", "q": "shared"}, {"n": "Masking tape", "q": "shared"}, {"n": "Pipettes", "q": "per team"}, {"n": "Water", "q": "shared"}, {"n": "Pepper or cocoa", "q": "residue"}, {"n": "Ramps", "q": "per team"}], "steps": [{"t": "Compare bare surfaces", "b": "Drop water on smooth and rough surfaces. Watch which makes the droplet bead up."}, {"t": "Texture and coat", "b": "Add micro-texture and a water-repelling layer to your test surface."}, {"t": "Add a dirt challenge", "b": "Sprinkle pepper or cocoa as fake dirt. A good surface carries it off with the droplet."}, {"t": "Race down the ramp", "b": "Run droplets down the standard ramp. Time the runoff and check the residue left behind."}, {"t": "Redesign for less residue", "b": "Adjust texture or coating to shed cleaner, then re-run."}], "compete": ["Fast clean runoff: 35", "Least residue: 25", "Surface design explanation: 20", "Redesign gain: 10", "Craftsmanship: 10"], "scoring": "Best clean runoff and least residue after one redesign wins.", "debrief": ["Why does a rough, waxy surface shed water better than a smooth one?", "What carried the dirt away?", "Where would a self-cleaning surface be useful?"], "source": "AskNature Lotus Leaf Self-Cleaning Surface", "camp": "trees"}, {"code": "TTT-12", "t": "Leaf Stomata Microscope Detective", "sub": "Count stomata and rank leaves by water strategy", "cat": "field", "icon": "🔬", "buildMin": 80, "mission": "Count the breathing pores and rank leaves by how they manage water.", "science": [{"t": "Stomata: pores for gas exchange", "demo": null, "b": "Leaves breathe through tiny pores called stomata. They open to take in carbon dioxide and let oxygen out, but open stomata also lose water. The number and spacing of stomata reflect how a plant balances feeding itself against drying out."}, {"t": "Sampling and counting", "demo": null, "b": "You make a safe leaf peel or use prepared slides, count stomata in several fields of view, and average. Comparing counts across leaves lets you rank them by water strategy with real data."}], "materials": [{"n": "Leaf samples", "q": "varied"}, {"n": "Clear tape", "q": "shared"}, {"n": "Clear nail polish or slides", "q": "shared"}, {"n": "USB microscopes or magnifiers", "q": "per team"}, {"n": "Grid sheets", "q": "per team"}, {"n": "Gloves", "q": "per student"}], "steps": [{"t": "Make a safe peel", "b": "Paint clear polish on the leaf underside, let it dry, and lift the print with clear tape. Or use a prepared slide."}, {"t": "Focus the field", "b": "Place the peel under the microscope and focus until the stomata are sharp."}, {"t": "Count several fields", "b": "Count stomata in three or more fields of view and average to reduce error."}, {"t": "Compare leaves", "b": "Repeat for different leaves and build a team data table of counts per field."}, {"t": "Rank by water strategy", "b": "Use your counts to rank leaves from water-saving to water-spending, citing the data."}], "compete": ["Slide or peel quality: 25", "Counting accuracy: 30", "Ranking evidence: 25", "Team data table: 10", "Cleanup and care: 10"], "scoring": "Most accurate detective ranking with clean data and strong evidence wins.", "debrief": ["Why count several fields instead of one?", "What does a high stomata count suggest about a leaf's habitat?", "Where might error sneak into your count?"], "source": "Leaf stomata microscopy adaptations; Science Buddies plant biology", "camp": "trees"}];
const PY_DECK = [{"code":"PYS-00","welcome":true,"t":"Welcome to PY-STEM","sub":"Predict. Build. Test. Defend. Five days of missions.","cat":"biomed","icon":"🔬","buildMin":0,"mission":"Get oriented, meet your team, and learn how the week works: predict it, build or solve it, test it, then defend your result with data.","camp":"pystem","science":[{"t":"The week ahead","demo":null,"b":"PY-STEM is a week of hands-on missions in physics, biomedicine, and computer science. Every station runs the same loop: predict what will happen, build or solve it, test it, get scored, then redesign and defend your result with data."},{"t":"How you win","demo":null,"b":"Each station is scored out of 100 for design, data, teamwork, and explaining, so a fast finish does not win on its own. Your week counts your best 9 of 12 stations, and improving after a redesign earns a comeback bonus."},{"t":"Tickets, awards, and prizes","demo":null,"b":"Your team earns tickets for safety, teamwork, sharp questions, and creative designs, and spends them at the store just for fun, so they never change your score. There are daily awards plus end prizes for the top teams and the most improved."},{"t":"Safety first, indoors","demo":null,"b":"We work indoors all week. Listen for your team's safety captain, keep your space and the floor clear, walk between stations, and tell a counselor about any spill, cut, or injury right away."},{"t":"Small parts and hot glue","demo":null,"b":"Some stations use tiny magnets and glue guns. Never put magnets or small parts in your mouth, because swallowing two magnets is a medical emergency. Only staff run the low-temp glue guns, and you keep your fingers clear of the tip."},{"t":"Messy and springy stations","demo":null,"b":"At the oobleck station, keep it inside its bag and never pour it down a drain, and tell a counselor if you have a corn allergy. At the slinky station, keep it flat on the floor and never let go while it is stretched."}],"materials":[{"n":"Activity handout","q":"1 per camper"},{"n":"Pencil","q":"1 per camper"},{"n":"Name tag (card or masking tape)","q":"1 per camper"},{"n":"Safety gear","q":"staged at each station"}],"steps":[{"t":"Welcome and names","b":"Say hello, learn the room and the week, and put on your name tag (a card or masking tape)."},{"t":"Form your team","b":"Join one of the teams and pick a quick team name with your counselor."},{"t":"Safety walk","b":"Counselors point out the exits, the glue-gun and tiny-magnet rules, and where spills and scraps go."},{"t":"First mission","b":"Head into the first station and start the predict, build, test, defend loop."}],"compete":["Design and build: 30","Clean data: 25","Teamwork: 20","Explanation and defense: 25"],"scoring":"This is how every station is scored. Your week total is your best 9 of 12. The welcome itself is not scored.","debrief":["What is the first thing the loop asks you to do at every station?","Which safety rule will matter most at your first station?","This week, what will count as strong evidence for your design?"],"source":"PY-STEM 2026 camp orientation"}, {"code": "PYS-01", "t": "Magnetic Capsule Maze Cup", "sub": "Steer a pill-camera without touching it", "cat": "biomed", "icon": "🧲", "buildMin": 80, "mission": "Steer a magnetic pill-camera through a body maze without touching it.", "science": [{"t": "Remote actuation", "demo": "magnet", "b": "A magnet pulls a steel object through a barrier without contact. Doctors use the same idea to steer a swallowed capsule camera through the gut from outside the body. The field passes through the wall; only the magnetic force does the work."}, {"t": "Path planning", "demo": null, "b": "Move too fast and the capsule overshoots; move too slow and you waste time. You plan a route through the maze and control the external magnet to get a fast, clean run with the fewest wall touches."}], "materials": [{"n": "Small neodymium magnets", "q": "controlled count"}, {"n": "Maze boards", "q": "per team"}, {"n": "Steel tokens or paper clips", "q": "per team"}, {"n": "Timers", "q": "per team"}, {"n": "Barrier sheets", "q": "shared"}], "steps": [{"t": "Test the field through a barrier", "b": "Place the steel token on the maze and move a magnet under the board. Feel how the field pulls through."}, {"t": "Plan a route", "b": "Trace the maze path you will follow and mark tricky corners."}, {"t": "Practice control", "b": "Practice slow, steady moves. Sudden jerks make the token jump walls."}, {"t": "Run for time", "b": "Make a timed clean run. Each wall touch is a penalty."}, {"t": "Explain the control", "b": "Describe how distance and speed of the magnet changed your control."}], "compete": ["Fastest clean run: 50", "Low penalties: 20", "Magnetic-control explanation: 20", "Redesign: 10"], "scoring": "Fastest clean run with low penalties and a clear explanation wins.", "debrief": ["Why does moving the magnet slowly help?", "How does distance change the pull you feel?", "Where is remote actuation used in real medicine?"], "source": "Science Museum Group Magnetic Maze", "camp": "pystem"}, {"code": "PYS-02", "t": "Oobleck Armor Arena", "sub": "Armor from a liquid that hardens on impact", "cat": "materials", "icon": "🛡", "buildMin": 80, "mission": "Design armor with a material that acts like a liquid until impact.", "science": [{"t": "Shear-thickening fluids", "demo": "oobleck", "b": "Oobleck is cornstarch and water. Press it slowly and it flows like a liquid; hit it fast and it stiffens like a solid. Fast force jams the suspended particles together so they resist. This is shear thickening, and real impact-protection materials use the same trick."}, {"t": "Material efficiency", "demo": null, "b": "More material protects better but costs and weighs more. You optimize a sealed oobleck pad to protect a target with the least material, then test it with a controlled press, not a messy drop."}], "materials": [{"n": "Cornstarch", "q": "bulk"}, {"n": "Water", "q": "shared"}, {"n": "Zip bags", "q": "per team"}, {"n": "Cardboard sleeves", "q": "per team"}, {"n": "Test weights", "q": "shared"}, {"n": "Spoons and trays", "q": "per team"}], "steps": [{"t": "Mix and feel it", "b": "Mix cornstarch and water until it pours slowly but resists a fast poke."}, {"t": "Seal a pad", "b": "Double-bag a measured amount of oobleck to make a clean, sealed armor pad."}, {"t": "Protect the target", "b": "Place the pad over the target and apply the standard controlled press."}, {"t": "Trim the material", "b": "Reduce the oobleck while still protecting the target. Track how little you can use."}, {"t": "Reset clean", "b": "Show a clean reset with no leaks. Cleanup is scored."}], "compete": ["Protection result: 40", "Material efficiency: 20", "Explanation: 20", "Redesign: 10", "Cleanup: 10"], "scoring": "Best target protection with least material and cleanest reset wins.", "debrief": ["Why does a fast press feel harder than a slow one?", "How little oobleck still protected the target?", "Where would shear-thickening armor be useful?"], "source": "Science Buddies Oobleck; Exploratorium Ooze", "camp": "pystem"}, {"code": "PYS-03", "t": "Cardboard Automata Arcade", "sub": "One crank, one clever motion", "cat": "mechanics", "icon": "⚙", "buildMin": 80, "mission": "Build a one-crank machine that performs a mini task.", "science": [{"t": "Cams, followers, linkages", "demo": "cam", "b": "Turning a crank spins a cam. A follower rides on the cam and rises and falls as the shape passes, turning steady rotation into up-and-down or back-and-forth motion. Linkages pass that motion along. The cam shape decides the movement."}, {"t": "Reliability", "demo": null, "b": "A machine that jams is a failed machine. Smooth holes, low friction, and a steady crank make motion repeatable. You build a hand-cranked automaton that completes a task and runs reliably, then explain the mechanism."}], "materials": [{"n": "Cardboard", "q": "shared"}, {"n": "Skewers", "q": "shared"}, {"n": "Straws", "q": "bearings"}, {"n": "Craft sticks", "q": "shared"}, {"n": "Tape", "q": "shared"}, {"n": "Hot glue", "q": "staff station"}, {"n": "Scissors", "q": "per team"}], "steps": [{"t": "Build the box and shaft", "b": "Make a sturdy box and pass a skewer through straw bearings so it turns freely."}, {"t": "Cut a cam", "b": "Cut a cam disc and glue it firmly to the shaft so it cannot slip. An off-center or oval cam gives more motion."}, {"t": "Add a follower", "b": "Glue a straw into the frame as a guide, then slide a vertical rod through it to rest on the cam so it rises and falls freely as you crank."}, {"t": "Top it with a task", "b": "Attach a character or tool that performs a mini task as the follower moves."}, {"t": "Tune for reliability", "b": "Reduce friction and wobble so it runs the same every turn."}], "compete": ["Reliable motion: 30", "Cam or linkage complexity: 20", "Task success: 20", "Explanation: 20", "Aesthetics and build quality: 10"], "scoring": "Most reliable motion with a useful mechanism and clear explanation wins.", "debrief": ["How did your cam shape change the motion?", "What caused jams, and how did you fix them?", "Where do cams show up in real machines?"], "source": "Exploratorium Cardboard Automata", "camp": "pystem"}, {"code": "PYS-04", "t": "Stethoscope Sprint and Recovery", "sub": "Build a listening tool, measure like a scientist", "cat": "biomed", "icon": "🩺", "buildMin": 80, "mission": "Build a medical listening tool and use it like a sports scientist.", "science": [{"t": "Sound transmission", "demo": null, "b": "A stethoscope collects faint body sounds with a wide funnel and channels them through a tube to your ear. A sealed air path and a good funnel make quiet heartbeats audible. Materials and seal quality decide how well it works."}, {"t": "Heart rate and recovery", "demo": null, "b": "After light exercise, heart rate rises and then recovers. With consent, you measure resting and post-activity rates and watch recovery. Respectful, accurate data collection is part of the score."}], "materials": [{"n": "Funnels", "q": "per team"}, {"n": "Flexible tubing", "q": "per team"}, {"n": "Tape", "q": "shared"}, {"n": "Balloons or membranes", "q": "shared"}, {"n": "Stopwatches", "q": "per team"}, {"n": "Sanitizing wipes", "q": "shared"}], "steps": [{"t": "Build the stethoscope", "b": "Attach a funnel to tubing and seal the joints so no air leaks."}, {"t": "Add a diaphragm", "b": "Stretch a balloon membrane over the funnel to pick up faint sounds, optional."}, {"t": "Test sound quality", "b": "Listen for a clear heartbeat. Improve the seal until it is easy to hear."}, {"t": "Collect resting data", "b": "With consent, count the pulse at the wrist or neck over a timed window. If the stethoscope is hard to hear, the wrist or neck count still works."}, {"t": "Measure recovery", "b": "After light activity, measure how heart rate returns toward rest. Sanitize shared parts."}], "compete": ["Sound quality: 30", "Measurement accuracy: 25", "Explanation: 20", "Redesign: 15", "Data clarity: 10"], "scoring": "Best sound quality plus accurate, respectful data collection wins.", "debrief": ["What change most improved your sound quality?", "Why does a good seal matter so much?", "What does a fast recovery suggest?"], "source": "Science Buddies Make a Stethoscope", "camp": "pystem"}, {"code": "PYS-05", "t": "Reaction Time Combine", "sub": "Prove which strategy cuts your delay", "cat": "biomed", "icon": "⚡", "buildMin": 80, "mission": "Train like a sports scientist and prove which strategy cuts delay.", "science": [{"t": "From signal to muscle", "demo": null, "b": "Reaction time is the delay between seeing a signal and moving. The eye sends a signal to the brain, the brain decides, and nerves fire the muscle. The classic ruler-drop test turns that delay into a distance you can measure."}, {"t": "Median and improvement", "demo": null, "b": "One trial is noisy, so you take many and use the median. Then you test whether a strategy, like focusing or warming up, actually improves your number. Clean data and real improvement both score."}], "materials": [{"n": "Meter sticks", "q": "per team"}, {"n": "Reaction-time strip (cm to ms)", "q": "per team"}, {"n": "Score sheets", "q": "per team"}, {"n": "Clipboards", "q": "6"}], "steps": [{"t": "Run the ruler drop", "b": "A partner drops a meter stick; you catch it. Read the catch distance in cm, then use the cm-to-ms strip to turn it into your reaction time."}, {"t": "Take many trials", "b": "Record at least ten catches. Use the median, not the best single catch."}, {"t": "Pick a strategy", "b": "Choose one strategy to test: focus cue, warm-up, or eyes on the release point."}, {"t": "Retest and compare", "b": "Run another set with the strategy. Compare medians to see if it helped."}, {"t": "Show the data", "b": "Present a clear before-and-after with your median and spread."}], "compete": ["Best median reaction time: 35", "Data quality: 20", "Strategy improvement: 20", "Explanation: 15", "Teamwork: 10"], "scoring": "Best median plus most improvement using clean data wins.", "debrief": ["Why use the median instead of your fastest catch?", "Which strategy helped, and why might it?", "Where does reaction time matter in real life?"], "source": "Science Buddies Reaction Time", "camp": "pystem"}, {"code": "PYS-06", "t": "SONAR Slinky Showdown", "sub": "Make invisible distance sensing visible", "cat": "waves", "icon": "〰", "buildMin": 80, "mission": "Make invisible distance sensing visible with a slinky pulse.", "science": [{"t": "Longitudinal waves", "demo": "wave", "b": "Push one end of a stretched slinky and a compression travels along it: a longitudinal wave, where the coils move back and forth along the direction of travel. Sound works the same way through air. The pulse reflects off the far end and returns."}, {"t": "Echo timing is ranging", "demo": null, "b": "If you know how fast a pulse travels and you time its round trip, you can compute distance. That is how SONAR and ultrasonic sensors measure range. You predict and interpret pulses at challenge stations."}], "materials": [{"n": "Metal slinkies", "q": "4 to 6"}, {"n": "Floor tape", "q": "shared"}, {"n": "Station cards", "q": "set"}, {"n": "Clipboards", "q": "6"}], "steps": [{"t": "Send a pulse", "b": "Stretch the slinky on the floor and push one end sharply to launch a compression pulse."}, {"t": "Watch the reflection", "b": "See the pulse travel, reflect off the held end, and come back."}, {"t": "Predict before testing", "b": "At each station, predict what the pulse will do, then test and check."}, {"t": "Time several round trips", "b": "Send one pulse, count 4 to 6 reflections, time the whole sequence, then divide for a steadier speed, the SONAR idea."}, {"t": "Solve the stations", "b": "Work the challenge cards as a team, explaining each prediction."}], "compete": ["Model and predictions: 35", "Station performance: 25", "Explanation: 20", "Team communication: 20"], "scoring": "Most correct wave predictions and station solutions wins.", "debrief": ["How is a slinky pulse like a sound wave?", "Why does timing an echo give distance?", "Where are ultrasonic sensors used?"], "source": "IIHS SONAR Slinky", "camp": "pystem"}, {"code": "PYS-07", "t": "Pinhole Precision Challenge", "sub": "The sharpest image, no lens", "cat": "optics", "icon": "📷", "buildMin": 80, "mission": "Build the sharpest camera image with no lens.", "science": [{"t": "Light travels in straight lines", "demo": "pinhole", "b": "A pinhole camera has no lens. Light from each point of a scene travels in a straight line through a tiny hole and lands on the screen, forming an upside-down image. Because the rays cross at the hole, the picture is flipped."}, {"t": "The aperture tradeoff", "demo": null, "b": "There is a BEST hole size. Too big is bright but blurry; too tiny is dim and also blurry, because light spreads out at a very small hole. You test a few sizes to find the sharpest, then redesign once."}], "materials": [{"n": "Cardstock", "q": "shared"}, {"n": "Foil", "q": "for aperture"}, {"n": "Tape", "q": "shared"}, {"n": "Pushpins or paper clips", "q": "shared"}, {"n": "Wax paper", "q": "for the screen"}, {"n": "Light source", "q": "shared"}], "steps": [{"t": "Build the viewer", "b": "Make a tube or box with a foil aperture at one end and a wax-paper screen at the other that you look through toward the light."}, {"t": "Punch a clean hole", "b": "Pierce a clean, round hole in the foil with a sharp pin, about pinhead size to start. Do not chase the tiniest hole you can make."}, {"t": "Find the image", "b": "Dim the room and aim at a bright source. Look through the wax paper for the upside-down image; a cut-out shape taped over the light makes the flip easy to see."}, {"t": "Tune the aperture", "b": "Try a slightly larger or smaller hole. Balance sharpness against brightness."}, {"t": "Explain the optics", "b": "Describe why the image is flipped and why hole size changes the result."}], "compete": ["Image clarity: 35", "Concept explanation: 25", "Build quality: 20", "Redesign: 10", "Speed: 10"], "scoring": "Best image clarity and concept explanation after one aperture redesign wins.", "debrief": ["Why is the image upside down?", "Why is there a best hole size, not just the smallest?", "How is this related to your eye?"], "source": "Exploratorium Personal Pinhole Theater; NASA JPL Pinhole Camera", "camp": "pystem"}, {"code": "PYS-08", "t": "Low-Ropes Force Map Relay", "sub": "Predict balance before the challenge proves you right", "cat": "mechanics", "icon": "⚖", "buildMin": 80, "mission": "Predict balance and stability before the balance challenge proves you right.", "science": [{"t": "Center of mass", "demo": null, "b": "Your center of mass is the average position of your weight. You stay balanced while it stays over your base of support. Lean too far and the line of gravity leaves the base, so you tip. Lowering your center of mass adds stability."}, {"t": "Mapping forces", "demo": null, "b": "At each balance challenge you predict where balance will be hard, then test it with your body and a partner. The four challenges: stand heels and back to a wall and lift your far foot or reach a coin; sit in a backless chair and stand without leaning forward; bend, grab your toes, and hop; and walk a taped line holding a weight at arm's length, then at your chest. Each works or fails for a center-of-mass reason. Accurate predictions and a clear debrief score."}], "materials": [{"n": "Balance challenge cards", "q": "set"}, {"n": "Center-of-mass templates", "q": "per team"}, {"n": "Backless chair", "q": "shared"}, {"n": "Painter-tape floor line", "q": "shared"}, {"n": "Coin and small weight", "q": "shared"}, {"n": "Clipboards", "q": "6"}], "steps": [{"t": "Read the challenge", "b": "Look at the next balance challenge card and the body position it asks for."}, {"t": "Predict balance points", "b": "On the card, mark whether it will work or fail, and where your center of mass moves."}, {"t": "Test it safely", "b": "Do the challenge next to a wall so you can catch yourself. Notice where you actually felt unstable."}, {"t": "Map the forces", "b": "Sketch where your weight acted and whether your center of mass stayed over your base of support."}, {"t": "Debrief the connection", "b": "Explain how lowering or shifting your center of mass changed stability."}], "compete": ["Correct predictions: 35", "Force-map quality: 25", "Debrief explanation: 20", "Teamwork reflection: 20"], "scoring": "Most accurate predictions and clear debrief connections wins.", "debrief": ["When did your prediction match what you felt?", "How did lowering your center of mass help?", "Where else does balance physics matter?"], "source": "TeachEngineering center-of-mass and balance references", "camp": "pystem"}, {"code": "PYS-09", "t": "Hovercraft Hockey Hackathon", "sub": "A puck that barely touches the floor", "cat": "mechanics", "icon": "🏒", "buildMin": 80, "mission": "Build a puck that moves by barely touching the floor.", "science": [{"t": "Air cushion cuts friction", "demo": "hover", "b": "A balloon pushes air down through a hole in a disc, lifting the disc on a thin cushion of air. With almost no contact, friction nearly vanishes, so a small push sends it gliding. Newton's laws then keep it moving until something stops it."}, {"t": "Glide versus control", "demo": null, "b": "Maximum glide is easy; control is hard. You balance lift and steerability to compete in gym-safe target hockey. Build quality and a clear explanation also score."}], "materials": [{"n": "Recycled CDs or discs", "q": "per team"}, {"n": "Pop-top bottle caps", "q": "per team"}, {"n": "Balloons", "q": "per team"}, {"n": "Hot glue", "q": "staff station"}, {"n": "Targets", "q": "shared"}, {"n": "Floor tape", "q": "shared"}], "steps": [{"t": "Mount the valve", "b": "Glue a pop-top cap over the center hole of the disc, sealing the edge."}, {"t": "Attach the balloon", "b": "Stretch an inflated balloon over the closed cap so air escapes only through the hole."}, {"t": "Test the glide", "b": "Open the cap just a little, set it down, and give a gentle push. A small opening glides longer and steers better; open wider only if it will not lift."}, {"t": "Practice control", "b": "Learn to start and stop on target. Too much lift means no control."}, {"t": "Play target hockey", "b": "Compete in gym-safe rounds. Glide and control both count."}], "compete": ["Glide performance: 30", "Target competition score: 25", "Explanation: 20", "Redesign: 15", "Build quality: 10"], "scoring": "Best glide plus control in a gym-safe tournament wins.", "debrief": ["Why does the air cushion reduce friction?", "Why is more lift not always better?", "Where are air bearings used in real life?"], "source": "NASA JPL Hovering on a Cushion of Air; Science Buddies Hovercraft", "camp": "pystem"}, {"code": "PYS-10", "t": "Spectra Sleuth Showdown", "sub": "Two white lights, two hidden color fingerprints", "cat": "optics", "icon": "🌈", "buildMin": 80, "mission": "Can two white lights hide different color fingerprints?", "science": [{"t": "Diffraction splits light", "demo": "spectra", "b": "A diffraction grating bends different colors by different amounts, spreading light into a spectrum. Two lights that look the same white can have very different spectra: a smooth rainbow from a hot filament, a broad colored band from a white LED, or separated bright lines from a neon or gas source."}, {"t": "Spectra as fingerprints", "demo": null, "b": "Each light source has a characteristic spectrum, its fingerprint. This is the same science behind firework colors, where different metal salts emit specific colors. You match mystery sources to clue cards using their spectra, no flame needed."}], "materials": [{"n": "Diffraction glasses or gratings", "q": "per student"}, {"n": "White LED sources", "q": "shared"}, {"n": "Neon or gas light", "q": "shared"}, {"n": "Incandescent source", "q": "if available"}, {"n": "Spectrum cards", "q": "set"}, {"n": "Museum clue sheets", "q": "per team"}], "steps": [{"t": "Look through the grating", "b": "View a white light through the grating and watch it spread into colors."}, {"t": "Compare two sources", "b": "Look at a white LED and a neon light. The LED shows a broad band; the neon shows separate bright lines."}, {"t": "Sketch the spectra", "b": "Draw what you see for each mystery source: continuous band or separate lines."}, {"t": "Match to clue cards", "b": "Use your sketches to match each source to its spectrum card."}, {"t": "Connect to fireworks", "b": "Explain how this links to the colors in a firework display, safely."}], "compete": ["Correct matches: 40", "Spectrum sketches: 20", "Explanation: 20", "Exhibit connection: 20"], "scoring": "Most correct spectrum matches and strongest safe fireworks-science explanation wins.", "debrief": ["How can two white lights have different spectra?", "What does a line spectrum tell you?", "How do chemists make firework colors?"], "source": "Science History Institute Flash Bang Boom; Exploratorium Spectra", "camp": "pystem"}, {"code": "PYS-11", "t": "BookBot Bin Logic Challenge", "sub": "Retrieve by address, not by conveyor race", "cat": "cs", "icon": "📚", "buildMin": 80, "mission": "Retrieve the right book by using bin addresses, not a conveyor race.", "science": [{"t": "Automated storage and retrieval", "demo": "bookbot", "b": "Temple's Charles Library BookBot stores books in bins identified by an address, not by subject on a shelf. A crane fetches the bin by its address on request. The same logic runs warehouses: store anywhere, remember the address, retrieve on demand."}, {"t": "Routing and search", "demo": null, "b": "Good addressing and smart routing minimize travel and avoid traffic jams. You simulate storage and retrieval with order cards, bin addresses, and routing rules, then defend your algorithm."}], "materials": [{"n": "Bin cards", "q": "set"}, {"n": "Address labels", "q": "shared"}, {"n": "Order deck", "q": "per team"}, {"n": "Route mat", "q": "per team"}, {"n": "Timers", "q": "per team"}, {"n": "Grabber tool", "q": "optional"}], "steps": [{"t": "Set up the bins", "b": "Label bins with addresses and place items by address, not by subject."}, {"t": "Read an order", "b": "Draw an order card listing the items to retrieve and their addresses."}, {"t": "Plan the route", "b": "Order your retrievals to minimize travel and avoid collisions with other teams."}, {"t": "Run the retrieval", "b": "Fetch the items by address against the clock. Wrong items cost points."}, {"t": "Defend the algorithm", "b": "Explain the rule you used to choose the order and why it is efficient."}], "compete": ["Correct retrievals: 35", "Low traffic conflicts: 25", "Routing or algorithm explanation: 20", "Efficiency: 10", "Teamwork: 10"], "scoring": "Most correct retrievals with few traffic conflicts and a clear algorithm defense wins.", "debrief": ["Why store by address instead of by subject?", "What made one route faster than another?", "Where else is this storage logic used?"], "source": "Temple Charles Library BookBot; Charles Library Circulating Collections", "camp": "pystem"}, {"code": "PYS-12", "t": "Accessibility Ramp Rescue Lab", "sub": "A portable ramp that meets real constraints", "cat": "design", "icon": "♿", "buildMin": 80, "mission": "Design a portable ramp that works for a real user constraint.", "science": [{"t": "Slope, load, and universal design", "demo": "ramp", "b": "A ramp trades steepness for length: a gentler slope is easier and safer to use but needs more room. Accessibility standards cap how steep a ramp can be. Universal design means building for real users and real constraints from the start, not as an afterthought."}, {"t": "Criteria and constraints", "demo": null, "b": "Your client gives criteria: a maximum slope, a load to carry, and a portability limit. You build a scale ramp for a toy wheelchair or weighted cart that meets all of them, then defend the tradeoffs."}], "materials": [{"n": "Foam board", "q": "per team"}, {"n": "Craft sticks", "q": "shared"}, {"n": "Dowels", "q": "shared"}, {"n": "Binder clips", "q": "shared"}, {"n": "Rulers", "q": "per team"}, {"n": "Free-rolling or pull-back car", "q": "shared"}, {"n": "200 g hanging weight set", "q": "shared"}, {"n": "Tape", "q": "shared"}], "steps": [{"t": "Read the client criteria", "b": "Note the maximum slope, the required load, and the portability limit."}, {"t": "Sketch to meet the slope", "b": "Work out the ramp length that keeps the slope within the limit for the given height."}, {"t": "Build the scale ramp", "b": "Construct a sturdy ramp from foam board and supports that folds or carries easily."}, {"t": "Test in two steps", "b": "First roll the cart to check it runs smooth and straight; do not pile weights on the cart. Then bridge the ramp between two desks and hang the weights at the middle to check for sag."}, {"t": "Defend the tradeoffs", "b": "Explain how your design meets slope, load, and portability together."}], "compete": ["Load held: 30", "Slope meets target: 30", "Portability: 20", "Client criteria explanation: 20"], "scoring": "Best safe ramp meeting slope, load, portability, and client criteria wins.", "debrief": ["Why does a gentler slope need more length?", "Which criterion was hardest to meet?", "Why design for accessibility from the start?"], "source": "TeachEngineering Wheelchair Ramp Design", "camp": "pystem"}];
const TREESB_DECK = [{"code": "TTB-01", "t": "Root Grip Erosion Rescue", "sub": "Can roots hold a slope together in a storm?", "cat": "field", "icon": "🌊", "buildMin": 60, "mission": "Can roots hold a slope together during a storm?", "science": [{"t": "Roots anchor soil", "demo": null, "b": "Bare soil on a slope washes away fast when rain hits it. Roots grip the soil and hold it in place, and a denser, deeper root network holds better. This is why planting vegetation is a real tool for stopping erosion."}, {"t": "Slope and runoff", "demo": null, "b": "Steeper slopes and bare surfaces shed water and soil quickly. You build a mini slope with root-like anchors, pour a standard amount of water, and measure how much soil stays put."}], "materials": [{"n": "Trays", "q": "per team"}, {"n": "Soil", "q": "shared"}, {"n": "String or yarn roots", "q": "shared"}, {"n": "Craft sticks", "q": "shared"}, {"n": "Watering cups", "q": "per team"}], "steps": [{"t": "Build a bare slope", "b": "Pack soil into a tray at a set angle with no roots. This is your control."}, {"t": "Add root anchors", "b": "Push string or yarn roots into a second slope to mimic a planted hillside."}, {"t": "Pour the standard storm", "b": "Pour the same measured water on each slope from the same height."}, {"t": "Measure soil retained", "b": "Compare how much soil washed out of each tray. Record the difference."}, {"t": "Redesign the root network", "b": "Add more or deeper roots and re-test to retain more soil."}], "compete": ["Soil retained: 40", "Runoff control: 25", "Design explanation: 20", "Cleanup: 15"], "scoring": "Most soil retained after the standard pour wins.", "debrief": ["Why did the rooted slope hold more soil?", "How would deeper roots change the result?", "Where is this used to protect real hillsides?"], "source": "EPA green infrastructure and erosion lessons", "camp": "trees"}, {"code": "TTB-02", "t": "Tree Height Triangulation Shootout", "sub": "Measure a tree without climbing it", "cat": "field", "icon": "📐", "buildMin": 60, "mission": "Measure a tree without climbing it.", "science": [{"t": "Angles give height", "demo": null, "b": "You can find a tree's height without touching the top. Sight the treetop through a paper clinometer to read an angle, measure your distance to the trunk, and the geometry of a right triangle gives the height. This is remote sensing with a protractor."}, {"t": "Accuracy from method", "demo": null, "b": "Small sighting errors grow over distance, so careful technique matters: level your eye, sight steadily, measure distance honestly. The team closest to the instructor's reference height wins."}], "materials": [{"n": "Paper clinometers", "q": "per team"}, {"n": "String and washers", "q": "shared"}, {"n": "Rulers and tape measures", "q": "shared"}, {"n": "Clipboards", "q": "4 (one per team)"}], "steps": [{"t": "Build the clinometer", "b": "Fold a paper clinometer with a weighted string plumb line to read angles."}, {"t": "Pace a known distance", "b": "Measure your straight-line distance from the trunk and record it."}, {"t": "Sight the treetop", "b": "Look along the clinometer at the very top and read the angle steadily."}, {"t": "Compute the height", "b": "Use the angle, your distance, and your eye height to estimate the tree height."}, {"t": "Check against reference", "b": "Compare to the instructor reference. The closest estimate wins."}], "compete": ["Accuracy: 50", "Method clarity: 20", "Speed: 20", "Teamwork: 10"], "scoring": "Closest estimate to the instructor reference height wins.", "debrief": ["What was your biggest source of error?", "Why does eye height matter in the calculation?", "Where is remote height measurement used in the field?"], "source": "GLOBE Trees Activities", "camp": "trees"}, {"code": "TTB-03", "t": "Urban Heat Shade Dash", "sub": "Find the coolest route through a hot campus", "cat": "data", "icon": "🌡", "buildMin": 60, "mission": "Find the coolest route through a hot campus.", "science": [{"t": "Urban heat and shade", "demo": null, "b": "Paved, sunlit surfaces get much hotter than shaded or planted ones. Shade from trees and buildings can drop surface temperature sharply over a few steps. Mapping these differences reveals cooler paths through a hot space."}, {"t": "Data-backed routing", "demo": null, "b": "You measure shaded and sunny surfaces, then design a cool corridor: a route that keeps people on the coolest surfaces. The best route is justified by your own temperature data."}], "materials": [{"n": "Thermometers or IR thermometers", "q": "per team"}, {"n": "Campus maps", "q": "per team"}, {"n": "Clipboards", "q": "4 (one per team)"}], "steps": [{"t": "Measure sun vs shade", "b": "Record surface temperature in matched sunny and shaded spots."}, {"t": "Map the hot spots", "b": "Mark the hottest and coolest surfaces on your map."}, {"t": "Design a cool corridor", "b": "Plot a walking route that stays on the coolest surfaces."}, {"t": "Justify with data", "b": "Show the temperatures that make your route cooler than the direct path."}, {"t": "Communicate the plan", "b": "Present the route clearly so someone could follow it."}], "compete": ["Cool route design: 35", "Data quality: 25", "Reasoning: 20", "Communication: 20"], "scoring": "Best data-backed cool route wins.", "debrief": ["How big was the sun-to-shade temperature gap?", "What surface was hottest, and why?", "How do cities use shade to cool streets?"], "source": "NASA MyNASAData Urban Heat Island", "camp": "trees"}, {"code": "TTB-04", "t": "Photosynthesis Float-Off Playoffs", "sub": "Make leaf disks float by making oxygen", "cat": "field", "icon": "🪴", "buildMin": 60, "mission": "Make leaf disks float by producing oxygen.", "science": [{"t": "Photosynthesis makes oxygen", "demo": null, "b": "Leaf disks sink when the air is drawn out of them. In light, with carbon dioxide available from a baking-soda solution, the leaf photosynthesizes and produces oxygen. The oxygen collects inside the disk until it floats. Floating is direct evidence of photosynthesis."}, {"t": "Controlled variables", "demo": null, "b": "Light level, carbon-dioxide concentration, and temperature all change the rate. You run a controlled assay, change one variable, and time how long until half the disks float."}], "materials": [{"n": "Spinach leaves", "q": "shared"}, {"n": "Baking soda solution", "q": "shared"}, {"n": "Cups", "q": "per team"}, {"n": "Oral syringes, no needle", "q": "per team"}, {"n": "Timers", "q": "per team"}], "steps": [{"t": "Cut and sink the disks", "b": "Punch leaf disks, then use a needle-free syringe to pull the air out so they sink."}, {"t": "Set up the solution", "b": "Place disks in baking-soda solution to supply carbon dioxide."}, {"t": "Add light", "b": "Put the cup under a light source to drive photosynthesis."}, {"t": "Time the half-float", "b": "Record the time until half the disks rise to the surface."}, {"t": "Change one variable", "b": "Adjust light or carbon-dioxide level, hold the rest constant, and compare rates."}], "compete": ["Performance: 35", "Controlled-variable design: 25", "Data table: 20", "Explanation: 10", "Cleanup: 10"], "scoring": "Fastest half-float time with controlled variables wins.", "debrief": ["Why does oxygen make the disks float?", "Which variable changed the rate most?", "How is this evidence of photosynthesis?"], "source": "Exploratorium Photosynthetic Floatation", "camp": "trees"}];
const PYB_DECK = [{"code": "PYB-01", "t": "Pencil Pressure Safety Lab", "sub": "Spread a force before it dents the target", "cat": "mechanics", "icon": "📌", "buildMin": 60, "mission": "Spread a force before it dents the target.", "science": [{"t": "Pressure vs force", "demo": null, "b": "Pressure is force divided by area. The same push on a sharp point dents a surface, but spread over a wide area it does not. That is why a sharp pencil pierces and a flat board does not: same force, different area."}, {"t": "Spreading stress", "demo": null, "b": "Safety design often means spreading a load so no single spot takes too much. You design a spreader that protects foam from a standard load and show the protected area with data."}], "materials": [{"n": "Pencils", "q": "shared"}, {"n": "Foam", "q": "per team"}, {"n": "Cardboard", "q": "shared"}, {"n": "Weights", "q": "shared"}, {"n": "Graph paper", "q": "per team"}], "steps": [{"t": "Test the bare point", "b": "Lay graph paper over the foam. Press the same load through a pencil point and record whether it pierces the paper (yes or no)."}, {"t": "Design a spreader", "b": "Build a cardboard spreader that distributes the same load over more area."}, {"t": "Apply the standard load", "b": "Press the same weight through your spreader onto fresh foam."}, {"t": "Measure protected area", "b": "Trace the spreader footprint on the graph paper and count the squares. No pierce over more squares means lower pressure."}, {"t": "Redesign for more spread", "b": "Improve the spreader to protect a larger area and re-test."}], "compete": ["Pressure spread: 40", "Explanation: 25", "Data quality: 20", "Redesign: 15"], "scoring": "Largest area protected with clear data wins.", "debrief": ["Why does the same force do less damage over more area?", "Where is this used in safety gear?", "What made your spreader better?"], "source": "IIHS Pencil Pressure", "camp": "pystem"}, {"code": "PYB-02", "t": "Domino Neuron Relay", "sub": "Make a nerve signal survive a gap", "cat": "biomed", "icon": "🂠", "buildMin": 60, "mission": "Make a nerve signal survive a gap.", "science": [{"t": "Signals travel in a chain", "demo": null, "b": "A line of falling dominoes is a model of a nerve signal: each one knocks the next, so the signal travels without any single domino moving far. A real neuron passes a signal down its length the same way, one step triggering the next."}, {"t": "Gaps and insulation", "demo": null, "b": "If the gap between dominoes is too large, the signal dies. Neurons face the same problem at synapses. A myelin sheath speeds signals along; you model gaps and insulation to keep the relay fast and reliable."}], "materials": [{"n": "Dominoes", "q": "per team"}, {"n": "Rulers", "q": "per team"}, {"n": "Tape", "q": "shared"}, {"n": "Index cards", "q": "shared"}], "steps": [{"t": "Build a baseline track", "b": "Tape paper down so tiles cannot slide, set dominoes evenly with each gap smaller than a tile is tall, then time one full run."}, {"t": "Introduce a gap", "b": "Open a larger gap and see whether the signal still crosses."}, {"t": "Bridge the gap", "b": "Add a bridge piece, like a synapse helper, so the signal survives."}, {"t": "Speed it up like myelin", "b": "Tape a few tiles into rigid blocks that fall as one unit, so the signal jumps block to block and reaches the end faster than the evenly spaced line."}, {"t": "Explain the analogy", "b": "Connect your design choices to neurons, synapses, and myelin."}], "compete": ["Transmission success: 35", "Gap challenge: 25", "Explanation: 20", "Redesign: 20"], "scoring": "Fastest reliable signal with the best explanation wins.", "debrief": ["What happened when the gap got too wide?", "How is a bridge piece like a synapse?", "Why does myelin speed real signals?"], "source": "Exploratorium Domino Effect", "camp": "pystem"}, {"code": "PYB-03", "t": "Pulley Rescue Relay", "sub": "Lift the load with smarter force, not stronger arms", "cat": "mechanics", "icon": "🔗", "buildMin": 60, "mission": "Lift the load with smarter force, not stronger arms.", "science": [{"t": "Mechanical advantage", "demo": null, "b": "A single fixed pulley just changes the direction of your pull. Add movable pulleys and you trade distance for force: you pull more rope but with less effort. More supporting rope segments means more mechanical advantage."}, {"t": "Force and direction", "demo": null, "b": "Pulleys let you pull down to lift up, and let a small force raise a big load. You build pulley systems, compare the effort needed, and explain why the setup helps."}], "materials": [{"n": "Classroom pulleys", "q": "per team"}, {"n": "String", "q": "shared"}, {"n": "Weights", "q": "shared"}, {"n": "Spring scales", "q": "per team"}], "steps": [{"t": "Lift with no pulley", "b": "Measure the effort to lift the load by hand as a baseline."}, {"t": "Add a fixed pulley", "b": "Reroute over one fixed pulley. Note that direction changes but effort does not."}, {"t": "Add a movable pulley", "b": "Build a system with a movable pulley and feel the effort drop."}, {"t": "Measure the advantage", "b": "Use a spring scale to compare effort across setups; keep the load heavy enough to read clearly."}, {"t": "Explain the tradeoff", "b": "Show how more rope segments cut the force you need."}], "compete": ["Performance: 35", "Setup accuracy: 25", "Explanation: 20", "Teamwork: 20"], "scoring": "Best lift with the correct setup and a clear explanation wins.", "debrief": ["Why did the movable pulley reduce effort?", "What did you trade for the easier lift?", "Where are pulley systems used in rescue work?"], "source": "TryEngineering Pulleys and Force", "camp": "pystem"}, {"code": "PYB-04", "t": "Barcode Checksum Rescue", "sub": "Catch the fake barcode before the warehouse ships the wrong part", "cat": "cs", "icon": "🔖", "buildMin": 60, "mission": "Catch the fake barcode before the warehouse ships the wrong part.", "science": [{"t": "Check digits catch errors", "demo": null, "b": "A barcode includes an extra check digit computed from the others by a fixed rule. If a digit is mistyped or smudged, the rule no longer matches and the scanner rejects the code. This is how real product codes catch errors automatically."}, {"t": "Detect without false alarms", "demo": null, "b": "A good detector flags the truly bad codes while passing the good ones. You race to find corrupted codes, keep false alarms low, and explain the check-digit rule you used."}], "materials": [{"n": "Printed barcode cards", "q": "set"}, {"n": "Dry erase boards", "q": "per team"}, {"n": "Timers", "q": "per team"}], "steps": [{"t": "Learn the rule", "b": "Study the check-digit rule: how the last digit is computed from the rest."}, {"t": "Verify a good code", "b": "Apply the rule to a valid code and confirm it checks out."}, {"t": "Hunt corrupted codes", "b": "Scan a deck of cards and flag the ones that fail the rule."}, {"t": "Avoid false alarms", "b": "Double-check before flagging; wrongly rejecting a good code costs points."}, {"t": "Explain the rule", "b": "Describe how the check digit catches a single mistyped digit."}], "compete": ["Correct detections: 45", "Low false alarms: 20", "Rule explanation: 20", "Teamwork: 15"], "scoring": "Most bad codes detected with few false alarms wins.", "debrief": ["How does one extra digit catch a typo?", "Why do false alarms matter in a warehouse?", "Where do you see check digits in daily life?"], "source": "Computer science unplugged error-detection concepts", "camp": "pystem"}];

export { CATMAP, TREES_DECK, PY_DECK, TREESB_DECK, PYB_DECK };
